with with_latest as (select s.*, x.employee_job_title from departments s left join lateral (select c.job_title as employee_job_title from employees c where c.dept_id = s.id order by c.hire_date desc, c.id desc limit 1) x on true), base as (select id, location, budget, employee_job_title, lower(location) as location_lower, coalesce(dept_name, 'DIRECT') as resolved_dept_name from with_latest where dept_name = 'Sales'), scored as (select *, avg(budget) over (partition by employee_job_title, location order by budget, id rows between 2 preceding and current row) as last3_avg_budget, sum(budget) over (partition by employee_job_title, location order by budget, id rows between 2 preceding and current row) as last3_sum_budget, count(budget) over (partition by employee_job_title, location order by budget, id rows between 2 preceding and current row) as last3_count_budget from base), with_last as (select s.id, s.location, s.budget, s.employee_job_title, s.last3_sum_budget, s.last3_count_budget, top1.employee_job_title_2 from scored s left join lateral (select c.job_title as employee_job_title_2 from employees c where c.dept_id = s.id order by c.salary desc, c.id desc limit 1) top1 on true) select * from (select employee_job_title, location, budget from with_last) src pivot (sum(budget) as amount, count(1) as n for location in ('Tokyo', 'Bangkok', 'London'));
